let activeLang=currentLang;
function localizeItem(item){
 const [name,desc,price]=item;
 const t=menuTranslations[activeLang]&&menuTranslations[activeLang][name];
 return t?[t[0],t[1],price]:item;
}
const originalRender=render;
render=function(cat){
 document.querySelectorAll('.menu-tabs button').forEach(b=>{const active=b.dataset.cat===cat;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));const key='tab_'+cat;if(menuLabels[activeLang]&&b.dataset.cat===cat)b.textContent=menuLabels[activeLang][cat]||b.textContent;});
 const list=menus[cat].slice().sort((a,b)=>{const o=menuOrder[cat]||[];return (o.indexOf(a[0])<0?999:o.indexOf(a[0]))-(o.indexOf(b[0])<0?999:o.indexOf(b[0]));});
 document.getElementById('menu-grid').innerHTML=list.map(item=>{const [n,d,p]=localizeItem(item);return '<article class="menu-item"><div><h3>'+n+'</h3>'+(d?'<p>'+d+'</p>':'')+'</div><div class="price">€ '+p+'</div></article>'}).join('');
};

function applyLanguage(lang){
 activeLang=lang;
 const t=langData[lang]||langData.it;
 document.documentElement.lang=lang;
 document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(t[key]!=null)el.innerHTML=t[key];});
 document.querySelector('.language-btn').textContent=lang.toUpperCase()+" ▾";
 document.querySelectorAll('.menu-tabs button').forEach(b=>{b.textContent=menuLabels[lang][b.dataset.cat]||b.textContent;});
 localStorage.setItem("laSostaLang",lang);
 const active=document.querySelector('.menu-tabs button.active');
 render(active?active.dataset.cat:"pizze");
}
const languageSwitcher=document.querySelector('.language-switcher');
const languageButton=document.querySelector('.language-btn');
const languageMenu=document.querySelector('.language-menu');
document.addEventListener('click',(event)=>{
 const choice=event.target.closest('.language-menu [data-lang]');
 if(choice){event.preventDefault();event.stopPropagation();applyLanguage(choice.dataset.lang);languageMenu.classList.remove('open');languageButton.setAttribute('aria-expanded','false');return;}
 if(event.target.closest('.language-btn')){event.preventDefault();event.stopPropagation();const open=!languageMenu.classList.contains('open');languageMenu.classList.toggle('open',open);languageButton.setAttribute('aria-expanded',String(open));return;}
 if(languageSwitcher&&!languageSwitcher.contains(event.target)){languageMenu.classList.remove('open');languageButton.setAttribute('aria-expanded','false');}
});
applyLanguage(activeLang);


