// --- Menu search / language completeness / privacy-friendly map ---
const menuSearchInput=document.getElementById('menu-search-input');
let menuSearchTerm='';
if(menuSearchInput){
  menuSearchInput.addEventListener('input',()=>{menuSearchTerm=menuSearchInput.value.trim().toLowerCase();const active=document.querySelector('.menu-tabs button.active');render(active?active.dataset.cat:'pizze');});
}
function filterMenu(list){
  if(!menuSearchTerm) return list;
  return list.filter(item=>item.join(' ').toLowerCase().includes(menuSearchTerm) || localizeItem(item).join(' ').toLowerCase().includes(menuSearchTerm));
}
const oldRenderForEnhance=render;
render=function(cat){
 document.querySelectorAll('.menu-tabs button').forEach(b=>{const active=b.dataset.cat===cat;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});
 const raw=(menus[cat]||[]).slice().sort((a,b)=>{const o=menuOrder[cat]||[];return (o.indexOf(a[0])<0?999:o.indexOf(a[0]))-(o.indexOf(b[0])<0?999:o.indexOf(b[0]));});
 const list=filterMenu(raw);
 const grid=document.getElementById('menu-grid');
 if(!list.length){grid.innerHTML='<div class="menu-empty">'+(langData[activeLang]?.menu_empty||'Nessun risultato. Prova con un altro termine.')+'</div>';return;}
 grid.innerHTML=list.map(item=>{const [n,d,p]=localizeItem(item);return '<article class="menu-item"><div><h3>'+n+'</h3>'+(d?'<p>'+d+'</p>':'')+'</div><div class="price">€ '+p+'</div></article>'}).join('');
};
if(menuSearchInput){
 const setSearchLanguage=()=>{
   const t=langData[activeLang]||langData.it;
   menuSearchInput.placeholder=t.menu_search_placeholder||'Pizza, pesce, tiramisù…';
   const label=document.querySelector('label[for="menu-search-input"]');
   if(label) label.textContent=t.menu_search_label||'Cerca nel menu';
 };
 setSearchLanguage();
 const originalApplyLanguage=applyLanguage;
 applyLanguage=function(lang){
   originalApplyLanguage(lang);
   const t=langData[activeLang]||langData.it;
   menuSearchInput.placeholder=t.menu_search_placeholder||'Pizza, pesce, tiramisù…';
   const label=document.querySelector('label[for="menu-search-input"]');
   if(label) label.textContent=t.menu_search_label||'Cerca nel menu';
 };
}
const mapButton=document.getElementById('load-map');
if(mapButton){
 mapButton.addEventListener('click',()=>{
   const area=document.getElementById('map-area');
   area.innerHTML='<iframe title="La Sosta su Google Maps" src="https://www.google.com/maps?q=La+Sosta%2C+Via+Buriasco+10%2F12%2C+10060+Piscina+TO&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe>';
 });
}

applyLanguage(activeLang);


